package Day2_Class_Assignment;
// menu driven food ordering
public class fifth {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("1. Biryani");
		System.out.println("2. Chicken punjabi");
		System.out.println("3. Palak paneer");
		int choice=2;
		switch(choice) {
			case 1:
				System.out.println("choosen choice 1");
				System.out.println("Biryani");
				break;
			case 2:
				System.out.println("choosen choice 2");
				System.out.println("Chicken punjabi");
				break;
			case 3:
				System.out.println("choosen choice 3");
				System.out.println("Palak paneer");
				break;
			default :
				System.out.println("Invalid choice");
	}
	}

}
